'''
const out = typeof $json === 'string' ? JSON.parse($json) : $json;
let reply = out.reply || '';
let stage = out.stage || 'qualifying';
let extracted = out.extracted || {};
let action = out.action || 'nudge';

// If the LLM wants to ask a question, build the reply from the prompt output
if (out.question) {
  reply = out.question;
  stage = 'qualifying';
}

return {
  reply: reply,
  stage: stage,
  extracted: extracted,
  action: action
};
'''
